@import "tailwindcss";

@theme {
  --color-bg-primary: #0d1117;
  --color-bg-secondary: #161b22;
  --color-bg-tertiary: #1c2333;
  --color-bg-card: #1a2030;
  --color-bg-card-hover: #1f2841;
  --color-border-primary: #30363d;
  --color-border-accent: #00d4ff33;
  --color-text-primary: #e6edf3;
  --color-text-secondary: #8b949e;
  --color-text-muted: #6e7681;
  --color-accent: #00d4ff;
  --color-accent-hover: #33ddff;
  --color-accent-dim: #00d4ff22;
  --color-accent-green: #3fb950;
  --color-accent-green-dim: #3fb95022;
  --color-accent-purple: #bc8cff;
  --color-accent-purple-dim: #bc8cff22;
  --color-accent-orange: #f0883e;
  --color-accent-orange-dim: #f0883e22;

  --font-sans: "Plus Jakarta Sans", system-ui, -apple-system, sans-serif;
  --font-mono: "JetBrains Mono", "Fira Code", ui-monospace, monospace;
  --font-display: "Space Grotesk", "Plus Jakarta Sans", system-ui, sans-serif;
}

@layer base {
  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    font-family: var(--font-sans);
    background-color: var(--color-bg-primary);
    color: var(--color-text-primary);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  ::selection {
    background-color: var(--color-accent-dim);
    color: var(--color-accent);
  }
}

@layer components {
  .glass-card {
    background: linear-gradient(135deg, rgba(26, 32, 48, 0.8), rgba(22, 27, 34, 0.6));
    border: 1px solid var(--color-border-primary);
    border-radius: 12px;
    backdrop-filter: blur(12px);
    transition: all 0.2s ease;
  }

  .glass-card:hover {
    border-color: var(--color-border-accent);
    box-shadow: 0 0 20px rgba(0, 212, 255, 0.06);
  }

  .code-block {
    background: var(--color-bg-primary);
    border: 1px solid var(--color-border-primary);
    border-radius: 8px;
    font-family: var(--font-mono);
    font-size: 14px;
    line-height: 1.6;
    padding: 16px 20px;
    overflow-x: auto;
    color: var(--color-text-primary);
  }

  .code-block .prompt {
    color: var(--color-accent-green);
    user-select: none;
  }

  .code-block .command {
    color: var(--color-text-primary);
  }

  .gradient-text {
    background: linear-gradient(135deg, var(--color-accent), var(--color-accent-purple));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .section-divider {
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--color-border-primary), transparent);
  }

  .noise-bg::before {
    content: '';
    position: fixed;
    inset: 0;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.03'/%3E%3C/svg%3E");
    pointer-events: none;
    z-index: 0;
  }

  .hero-glow {
    position: absolute;
    width: 600px;
    height: 600px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(0, 212, 255, 0.08) 0%, transparent 70%);
    pointer-events: none;
    top: -200px;
    left: 50%;
    transform: translateX(-50%);
  }
}

