import { useState, useEffect } from 'react'
import { siteConfig } from '@/config/site'
import { Menu, X, Search } from 'lucide-react'

export function Navigation({ currentPage }: { currentPage: string }) {
  const [mobileOpen, setMobileOpen] = useState(false)
  const [scrolled, setScrolled] = useState(false)

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20)
    window.addEventListener('scroll', onScroll)
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled
          ? 'bg-[#0d1117]/90 backdrop-blur-xl border-b border-[#30363d]'
          : 'bg-transparent'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <a href="/index.html" className="flex items-center gap-2.5 group">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-[#00d4ff] to-[#bc8cff] flex items-center justify-center">
              <span className="text-[#0d1117] font-bold text-sm font-[var(--font-display)]">CF</span>
            </div>
            <span className="text-[#e6edf3] font-semibold text-lg font-[var(--font-display)] tracking-tight">
              CommerceForge
            </span>
            <span className="text-[#6e7681] text-sm hidden sm:inline">Dev Docs</span>
          </a>

          {/* Desktop nav */}
          <div className="hidden md:flex items-center gap-1">
            {siteConfig.nav.items.map((item) => (
              <a
                key={item.label}
                href={item.href}
                className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                  currentPage === item.label.toLowerCase() ||
                  (currentPage === 'home' && item.label === 'Apps' && false)
                    ? 'text-[#00d4ff] bg-[#00d4ff]/10'
                    : 'text-[#8b949e] hover:text-[#e6edf3] hover:bg-[#1c2333]'
                }`}
              >
                {item.label}
              </a>
            ))}
          </div>

          {/* Right side */}
          <div className="flex items-center gap-3">
            <button
              className="p-2 rounded-lg text-[#8b949e] hover:text-[#e6edf3] hover:bg-[#1c2333] transition-colors"
              aria-label="Search"
            >
              <Search size={18} />
            </button>
            <a
              href={siteConfig.nav.login.href}
              className="hidden md:inline-flex px-4 py-1.5 rounded-lg text-sm font-medium border border-[#30363d] text-[#e6edf3] hover:bg-[#1c2333] transition-colors"
            >
              {siteConfig.nav.login.label}
            </a>
            <button
              className="md:hidden p-2 rounded-lg text-[#8b949e] hover:text-[#e6edf3]"
              onClick={() => setMobileOpen(!mobileOpen)}
              aria-label="Toggle menu"
            >
              {mobileOpen ? <X size={20} /> : <Menu size={20} />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile menu */}
      {mobileOpen && (
        <div className="md:hidden bg-[#0d1117]/95 backdrop-blur-xl border-b border-[#30363d]">
          <div className="px-4 py-3 space-y-1">
            {siteConfig.nav.items.map((item) => (
              <a
                key={item.label}
                href={item.href}
                className="block px-3 py-2 rounded-lg text-sm font-medium text-[#8b949e] hover:text-[#e6edf3] hover:bg-[#1c2333]"
                onClick={() => setMobileOpen(false)}
              >
                {item.label}
              </a>
            ))}
            <a
              href={siteConfig.nav.login.href}
              className="block px-3 py-2 rounded-lg text-sm font-medium text-[#00d4ff] hover:bg-[#00d4ff]/10"
            >
              {siteConfig.nav.login.label}
            </a>
          </div>
        </div>
      )}
    </nav>
  )
}

